package com.gymmind.nutrition.application; import com.gymmind.nutrition.domain.model.NutritionPlan; public record NutritionPlanView(Long id,Long tenantId,Long memberId,double caloriesTarget,double proteinTarget,double carbohydrateTarget,double fatTarget,String description){public static NutritionPlanView from(NutritionPlan p){return new NutritionPlanView(p.getId(),p.getTenantId(),p.getMemberId(),p.getCaloriesTarget(),p.getProteinTarget(),p.getCarbohydrateTarget(),p.getFatTarget(),p.getDescription());}}
